SELECT ?zone ?sensor WHERE {
  ?zone a brick:Zone .
  ?zone brick:hasName ?name .
  FILTER(?name IN ("Core_mid","Perimeter_bot_ZN_1","Perimeter_bot_ZN_4"))
  ?sensor brick:hasPropertyOf ?zone .
}

SELECT ?z ?p ?o WHERE {
  ?z a brick:Zone .
  ?z ?p ?o .
  FILTER(str(?o) = "Core_mid" || str(?o) = "Perimeter_bot_ZN_1" || str(?o) = "Perimeter_bot_ZN_4")
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?s ?l ?sensor ?ts WHERE {
  ?s rdfs:label ?l .
  FILTER(?l IN ("Core_mid","Perimeter_bot_ZN_1","Perimeter_bot_ZN_4"))
  OPTIONAL { ?sensor brick:isPointOf ?s ; brick:hasName ?sn . }
}

